"""
M365 Template Factory — fully self-contained, single-file portable.

Drop this file into ANY brainstem agents/ directory and it works.
Zero external file dependencies. Zero hard-coded paths.

The bottom of the file contains the generator code (proposed_rar_stacks/
_generate.py with the STACKS list and main() removed) inlined as plain
Python — readable, editable, debuggable. The Copilot Studio solution
template zip is the one piece that genuinely has to be binary; it's
embedded as a single base64 blob and decoded into ~/.rapp/m365_factory/
on first call.

Generated by proposed_rar_stacks/_build_portable_factory.py — do not
edit the embedded payload by hand. Re-run the bundler instead.
"""

