def pretty_folder(stack: dict) -> str:
    """Folder name for the deliverable bundle (matches m365-agent-templates style)."""
    return stack["name"]


def slug_camel(stack: dict) -> str:
    """CamelCase slug for solution zip filename, e.g. PurchaseOrderExtraction."""
    return "".join(p[:1].upper() + p[1:] for p in re.split(r"[\s_\-]+", stack["name"]) if p)


def industry_label(stack: dict) -> str:
    return stack["industry"].replace("_", " ").title()


