AGENT_TEMPLATE = '''"""{stack_name} agent — portable scaffold.

Drop into any AI-Agent-Templates-style repo at:
  agent_stacks/{industry}_stacks/{stack_id}_stack/agents/{agent_file}

Anonymous, industry-shaped. No PII. Designed to plug into the BasicAgent
runtime exposed by rapp_ai (or any compatible repo with `agents/basic_agent.py`).
"""

import sys
import os
sys.path.insert(0, os.path.abspath(os.path.join(os.path.dirname(__file__), "../../../../")))

from agents.basic_agent import BasicAgent
from datetime import datetime
import random


class {agent_class}(BasicAgent):
    def __init__(self):
        self.name = "{agent_class}"
        self.metadata = {{
            "name": self.name,
            "description": "{description}",
            "parameters": {{
                "type": "object",
                "properties": {{
                    "action": {{
                        "type": "string",
                        "enum": ["execute", "analyze", "report", "optimize"],
                        "description": "Action to perform",
                    }},
                    "entity_id": {{"type": "string", "description": "Unique identifier for the entity"}},
                    "data": {{"type": "object", "description": "Additional data for the operation"}},
                    "mode": {{
                        "type": "string",
                        "enum": ["real-time", "batch", "scheduled"],
                        "description": "Processing mode",
                    }},
                }},
                "required": ["action"],
            }},
        }}
        super().__init__(name=self.name, metadata=self.metadata)

    def perform(self, **kwargs):
        action = kwargs.get("action", "execute")
        if action == "execute":
            return self._execute(kwargs)
        if action == "analyze":
            return self._analyze(kwargs)
        if action == "report":
            return self._report(kwargs)
        if action == "optimize":
            return self._optimize(kwargs)
        return {{"status": "error", "message": f"Unknown action: {{action}}"}}

    def _execute(self, params):
        return {{
            "status": "success",
            "message": "{agent_class} executed successfully",
            "data": {{
                "operation_id": f"OP{{random.randint(100000, 999999)}}",
                "entity_id": params.get("entity_id", f"ENT{{random.randint(1000, 9999)}}"),
                "timestamp": datetime.now().isoformat(),
                "integrated_systems": {integrations!r},
            }},
        }}

    def _analyze(self, params):
        return {{"status": "success", "message": "Analysis completed", "data": {{}}}}

    def _report(self, params):
        return {{"status": "success", "message": "Report generated", "data": {{}}}}

    def _optimize(self, params):
        return {{"status": "success", "message": "Optimization applied", "data": {{}}}}
'''


def write_agent_py(stack: dict, dest: Path) -> None:
    code = AGENT_TEMPLATE.format(
        stack_name=stack["name"],
        industry=stack["industry"],
        stack_id=stack["id"],
        agent_file=stack["agent_file"],
        agent_class=stack["agent_class"],
        description=stack["description"].replace('"', '\\"'),
        integrations=stack["integrations"],
    )
    dest.write_text(code)


