def write_architecture(stack: dict, arch_dir: Path) -> None:
    arch_dir.mkdir(parents=True, exist_ok=True)
    cs = mermaid_copilot(stack)
    az = mermaid_azure(stack)
    (arch_dir / "copilot_studio.mmd").write_text(cs)
    (arch_dir / "azure_function.mmd").write_text(az)
    (arch_dir / "copilot_studio.html").write_text(MERMAID_HTML.format(
        title=f"{stack['name']} — Copilot Studio Native Architecture",
        subtitle="Native Copilot Studio deployment view",
        diagram=cs,
    ))
    (arch_dir / "azure_function.html").write_text(MERMAID_HTML.format(
        title=f"{stack['name']} — Azure Function (rapp_ai) Architecture",
        subtitle="Code-first deployment view via the rapp_ai Azure Function runtime",
        diagram=az,
    ))


