# =============================================================================
# Setup Guide PDF (canonical 7-section structure)
# =============================================================================

def _styles():
    s = getSampleStyleSheet()
    s.add(ParagraphStyle(name="HeroTitle", parent=s["Title"], fontSize=22, textColor=rl_colors.HexColor("#1F4ED8"), spaceAfter=4))
    s.add(ParagraphStyle(name="HeroSub", parent=s["Normal"], fontSize=11, textColor=rl_colors.HexColor("#444444"), spaceAfter=18))
    s.add(ParagraphStyle(name="H1Section", parent=s["Heading1"], fontSize=16, textColor=rl_colors.HexColor("#1F4ED8"), spaceBefore=14, spaceAfter=8))
    s.add(ParagraphStyle(name="H2Section", parent=s["Heading2"], fontSize=13, textColor=rl_colors.HexColor("#143799"), spaceBefore=10, spaceAfter=6))
    s.add(ParagraphStyle(name="Body", parent=s["BodyText"], fontSize=10.5, leading=14))
    s.add(ParagraphStyle(name="BulletItem", parent=s["BodyText"], fontSize=10.5, leading=14, leftIndent=14, bulletIndent=2))
    s.add(ParagraphStyle(name="Note", parent=s["BodyText"], fontSize=10, leading=13, textColor=rl_colors.HexColor("#665500"), backColor=rl_colors.HexColor("#FFF8DC"), borderPadding=6))
    return s


def _table_style():
    return TableStyle([
        ("BACKGROUND", (0, 0), (-1, 0), rl_colors.HexColor("#1F4ED8")),
        ("TEXTCOLOR", (0, 0), (-1, 0), rl_colors.white),
        ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
        ("FONTSIZE", (0, 0), (-1, -1), 9.5),
        ("BOTTOMPADDING", (0, 0), (-1, 0), 6),
        ("TOPPADDING", (0, 0), (-1, 0), 6),
        ("BACKGROUND", (0, 1), (-1, -1), rl_colors.HexColor("#FAFAFA")),
        ("ROWBACKGROUNDS", (0, 1), (-1, -1), [rl_colors.white, rl_colors.HexColor("#F4F7FF")]),
        ("GRID", (0, 0), (-1, -1), 0.5, rl_colors.HexColor("#E0E0E0")),
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
    ])


def write_setup_guide_pdf(stack: dict, dest: Path) -> None:
    s = _styles()
    name = stack["name"]
    slug = slug_camel(stack)
    doc = SimpleDocTemplate(str(dest), pagesize=LETTER, leftMargin=0.7*inch, rightMargin=0.7*inch, topMargin=0.7*inch, bottomMargin=0.7*inch, title=f"{name} Agent - Setup Guide")

    story: list = []
    P = lambda text, st="Body": Paragraph(text, s[st])

    # Cover
    story += [
        P(f"{name} Agent", "HeroTitle"),
        P("Setup &amp; Configuration Guide", "HeroSub"),
        P("A Custom Agent for Microsoft Copilot Studio", "Body"),
        P(f"Industry: <b>{industry_label(stack)}</b> · Version 1.0.0.1 · Last Updated: {TODAY}", "Body"),
        Spacer(1, 18),
    ]

    # TOC
    story += [P("Table of Contents", "H1Section")]
    toc_items = [
        f"1. What Is {name}?",
        "2. Before You Start (Prerequisites)",
        "3. Option A — Import the Solution into Copilot Studio",
        "4. Option B — Publish to Microsoft Teams &amp; Copilot Channels",
        "5. Option C — Build the Agent from Scratch in Copilot Studio",
        "6. Make It Your Own (Customization)",
        "7. Test That It Works",
    ]
    story += [P(f"• {t}", "BulletItem") for t in toc_items]
    story += [Spacer(1, 12)]

    # Which option
    story += [P("Which Option Should I Choose?", "H2Section")]
    opts = [
        ["Option", "Best For", "You'll Need", "Time"],
        ["Option A — Import", "Fastest setup — uses the pre-built solution package", "Copilot Studio access + solution .zip file", "~5 min"],
        ["Option B — Publish to Teams &amp; M365 Copilot", "Share the agent with your team via Teams", "Copilot Studio access + completed Option A", "~10 min"],
        ["Option C — Build from Scratch", "Full control — learn how every piece works", "Copilot Studio + Power Automate access", "~45 min"],
    ]
    t = Table([[Paragraph(c, s["Body"]) for c in row] for row in opts], colWidths=[1.5*inch, 2.0*inch, 2.0*inch, 0.8*inch])
    t.setStyle(_table_style())
    story += [t, Spacer(1, 14), PageBreak()]

    # 1. What Is X
    story += [
        P(f"1. What Is {name}?", "H1Section"),
        P(stack["description"], "Body"),
        Spacer(1, 6),
        P("What It Does", "H2Section"),
    ]
    phases = [
        ["Phase", "What Happens"],
        ["🔍 Capture", "Receives input (chat message, document, system event) and extracts the entities relevant to this stack."],
        ["🧠 Reason", "Calls the configured model (Azure OpenAI for the code-first path, hosted model for the Copilot Studio path) with the stack's instructions and any retrieved context."],
        ["⚡ Act", f"Invokes one or more of the listed integrations ({', '.join(stack['integrations'])}) to read or write the system of record."],
        ["📋 Respond", "Returns a structured, citation-backed answer to the user and persists state to Dataverse / D365."],
    ]
    pt = Table([[Paragraph(c, s["Body"]) for c in row] for row in phases], colWidths=[1.2*inch, 5.1*inch])
    pt.setStyle(_table_style())
    story += [pt, Spacer(1, 10)]

    story += [P("Built-in Suggested Prompts", "H2Section")]
    sp_rows = [["Title", "Prompt"]]
    for sx in stack["starters"]:
        title = sx[:42] + ("…" if len(sx) > 42 else "")
        sp_rows.append([title, sx])
    spt = Table([[Paragraph(c, s["Body"]) for c in row] for row in sp_rows], colWidths=[2.2*inch, 4.1*inch])
    spt.setStyle(_table_style())
    story += [spt, PageBreak()]

    # 2. Prereqs
    story += [
        P("2. Before You Start", "H1Section"),
        P("Make sure the items below are in place before proceeding with any option. If any are missing, contact your IT administrator.", "Body"),
        P("Checklist", "H2Section"),
    ]
    prereqs = [
        ["✓", "What You Need", "Why"],
        ["☐", "Microsoft 365 work account", "Required to sign in to Copilot Studio and Teams"],
        ["☐", "Microsoft Copilot Studio license", "Gives you access to build and run agents"],
        ["☐", "Access to a Power Platform environment", "The agent and its components live inside an environment"],
        ["☐", "System Customizer or System Administrator role", "Required to import the solution"],
        ["☐", f"{slug}_v1.0.0.0.zip file", "The solution package — do not unzip or rename it"],
    ]
    prt = Table([[Paragraph(c, s["Body"]) for c in row] for row in prereqs], colWidths=[0.3*inch, 2.5*inch, 3.5*inch])
    prt.setStyle(_table_style())
    story += [prt, PageBreak()]

    # 3. Option A
    story += [
        P("3. Option A — Import the Solution into Copilot Studio", "H1Section"),
        P("This is the fastest way to get started. You'll upload the pre-built solution package directly into Copilot Studio, which sets up everything — the agent, its topics, actions, and AI models — in one step.", "Body"),
        P("Import the Solution", "H2Section"),
    ]
    a_steps = [
        "Open your browser and go to <b>copilotstudio.microsoft.com</b>. Sign in with your Microsoft 365 work account.",
        "In the top-right corner, make sure the correct environment is selected.",
        "In the left navigation menu, click <b>Settings</b> (the gear icon ⚙️) at the bottom.",
        "Under the Settings menu, click <b>Solutions</b>. This opens the Solutions list page.",
        "Click the <b>Import</b> button at the top of the solutions list.",
        f"Click <b>Browse</b>, navigate to where you saved the <code>{slug}_v1.0.0.0.zip</code> file, select it, and click Open.",
        "Click <b>Next</b>. Copilot Studio will validate the package. Sign in for any connection references when prompted.",
        "Click <b>Import</b>. The import process may take 1–3 minutes. Wait for the green success banner.",
    ]
    for i, step in enumerate(a_steps, 1):
        story += [P(f"{i}. {step}", "BulletItem")]
    story += [Spacer(1, 6), P(f"✅ The solution is imported! The {name} agent is now in your environment.", "Note"), PageBreak()]

    # 4. Option B
    story += [
        P("4. Option B — Publish to Microsoft Teams &amp; Copilot Channels", "H1Section"),
        P("After importing the solution (Option A), make the agent available to colleagues through Microsoft Teams and Microsoft 365 Copilot.", "Body"),
        P("Step 1: Publish the Agent", "H2Section"),
        P(f"Open Copilot Studio, navigate to your <b>{name}</b> agent, and click <b>Publish</b> in the top-right corner. Wait for the green success confirmation.", "Body"),
        P("Step 2: Connect the Teams Channel", "H2Section"),
    ]
    b_steps = [
        "From the agent overview page, click <b>Channels</b> in the left navigation panel.",
        "Find <b>Microsoft Teams</b> in the list and click on it.",
        "Click <b>Turn on Teams</b> to enable the channel.",
        "Configure App Icon, Accent Color, Short Description, Long Description, and Developer Information.",
        "(Optional) Toggle on <b>Allow your users to add this agent to a team</b> for channel @mention support.",
    ]
    for i, step in enumerate(b_steps, 1):
        story += [P(f"{i}. {step}", "BulletItem")]
    story += [
        P("Step 3: Enable Microsoft 365 Copilot Channel", "H2Section"),
        P("Toggle <b>Microsoft 365 Copilot</b> on in the Channels page. This allows users to find the agent in the M365 Copilot side panel and @mention it in Copilot conversations.", "Body"),
        P("Step 4: Share with Others", "H2Section"),
        P("Three sharing methods are supported: direct installation link, <i>Built with Power Platform</i> visibility, or admin approval. Admin approval is recommended for broad organizational rollouts.", "Body"),
        PageBreak(),
    ]

    # 5. Option C
    story += [
        P("5. Option C — Build from Scratch in Copilot Studio", "H1Section"),
        P("This option walks you through building the entire agent from the ground up. Best if you want to deeply understand every piece or customize beyond what the imported solution provides.", "Body"),
        P("Part 1: Create the Agent", "H2Section"),
    ]
    c_part1 = [
        "Open Copilot Studio. In the left nav, click <b>Agents</b>, then <b>+ New agent</b>.",
        "Click <b>Skip to configure</b> at the bottom of the wizard.",
        f"Set <b>Name</b> = <code>{name}</code>.",
        f"Set <b>Description</b> = <i>{stack['description']}</i>",
    ]
    for i, step in enumerate(c_part1, 1):
        story += [P(f"{i}. {step}", "BulletItem")]

    story += [P("Part 2: Configure Instructions", "H2Section")]
    instructions = build_agent_instructions(stack)
    story += [P(f"Paste the following into the <b>Instructions</b> field:", "Body")]
    story += [P(f"<font face='Courier'>{escape_xml(instructions)}</font>", "Body")]

    story += [P("Part 3: AI Settings", "H2Section")]
    ai_steps = [
        "Enable <b>Web browsing</b> if the stack benefits from external context.",
        "Enable <b>Code interpreter</b> for structured-data tasks.",
        "Set <b>Content moderation</b> to <b>High</b> for responsible AI compliance.",
        "Enable <b>Generative actions</b> so the agent can call connected tools/flows.",
    ]
    for i, step in enumerate(ai_steps, 1):
        story += [P(f"{i}. {step}", "BulletItem")]

    story += [P("Part 4: Conversation Starters", "H2Section")]
    cs_rows = [["Title", "Prompt"]]
    for sx in stack["starters"]:
        title = sx[:42] + ("…" if len(sx) > 42 else "")
        cs_rows.append([title, sx])
    cst = Table([[Paragraph(c, s["Body"]) for c in row] for row in cs_rows], colWidths=[2.2*inch, 4.1*inch])
    cst.setStyle(_table_style())
    story += [cst, Spacer(1, 6)]

    story += [P("Part 5: Connectors / Knowledge", "H2Section")]
    story += [P(f"Wire connectors for the configured integrations: {', '.join(stack['integrations'])}. Add any required SharePoint sites or Dataverse tables as Knowledge sources.", "Body")]
    story += [PageBreak()]

    # 6. Customization
    story += [
        P("6. Make It Your Own", "H1Section"),
        P("Once the agent is running, you can customize it to fit your team's needs.", "Body"),
        P("What You Can Change", "H2Section"),
    ]
    cust_rows = [
        ["Customization", "How to Do It"],
        ["Change the agent's tone", "Edit the Instructions — adjust the language style and formality level."],
        ["Modify integration set", "Add/remove connectors in <b>Tools</b>. Update the instructions to reference any new tool."],
        ["Add or remove starter prompts", "Go to Conversation Starters and add/remove prompts."],
        ["Restrict to specific data scopes", f"Add scope restrictions to the Instructions (e.g., 'Only handle {industry_label(stack).lower()} requests')."],
        ["Wire up your code-first runtime", f"Deploy the BasicAgent variant in <code>agents/{stack['agent_file']}</code> behind your Azure Function App."],
    ]
    ct = Table([[Paragraph(c, s["Body"]) for c in row] for row in cust_rows], colWidths=[2.2*inch, 4.1*inch])
    ct.setStyle(_table_style())
    story += [ct, PageBreak()]

    # 7. Test
    story += [
        P("7. Test That It Works", "H1Section"),
        P("Quick Smoke Test", "H2Section"),
        P("Try these prompts to verify the agent is working correctly:", "Body"),
    ]
    test_rows = [["#", "Try This Prompt", "What to Look For"]]
    for i, sx in enumerate(stack["starters"], 1):
        test_rows.append([str(i), sx, "Agent should respond on-topic with structured output and (where appropriate) cited sources."])
    tt = Table([[Paragraph(c, s["Body"]) for c in row] for row in test_rows], colWidths=[0.3*inch, 2.7*inch, 3.3*inch])
    tt.setStyle(_table_style())
    story += [tt, Spacer(1, 8)]
    story += [P("For deeper coverage, see the <b>Evaluation Test Plan.pdf</b> alongside this guide.", "Body")]

    doc.build(story)


def escape_xml(s: str) -> str:
    return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")


# =============================================================================
# Evaluation Test Plan PDF
# =============================================================================

def write_eval_plan_pdf(stack: dict, dest: Path) -> None:
    s = _styles()
    name = stack["name"]
    doc = SimpleDocTemplate(str(dest), pagesize=LETTER, leftMargin=0.7*inch, rightMargin=0.7*inch, topMargin=0.7*inch, bottomMargin=0.7*inch, title=f"{name} Agent - Evaluation Test Plan")
    story = []
    P = lambda text, st="Body": Paragraph(text, s[st])

    story += [
        P(f"{name} Agent", "HeroTitle"),
        P("Evaluation Test Plan", "HeroSub"),
        P(f"Version 1.0.0.1 · Last Updated: {TODAY}", "Body"),
        Spacer(1, 14),
        P("Purpose", "H1Section"),
        P(f"This test plan defines pass/fail criteria for the {name} Agent. The accompanying CSV (Evaluation Test Set.csv) is importable directly into Copilot Studio's automated evaluation feature, but the criteria below also apply to manual evaluation in any Copilot Studio environment or against the code-first BasicAgent variant.", "Body"),
        P("Scope", "H1Section"),
        P(f"The agent is responsible for: {stack['description']} It is NOT responsible for: any out-of-scope requests outside the {industry_label(stack)} domain. The agent should politely redirect when asked to operate outside its scope.", "Body"),
        P("Test Approach", "H1Section"),
    ]
    appr_rows = [
        ["Method", "Description"],
        ["General quality", "Reviewer judges the response on relevance, accuracy, and structure against the expected response."],
        ["Keyword match", "Response must contain specific tokens (e.g., section headers, citation markers) defined in the test row."],
        ["Compare meaning", "Semantic similarity check: response should convey the same meaning as the expected response."],
    ]
    apt = Table([[Paragraph(c, s["Body"]) for c in row] for row in appr_rows], colWidths=[1.6*inch, 4.7*inch])
    apt.setStyle(_table_style())
    story += [apt, PageBreak()]

    # Test scenarios
    story += [P("Test Scenarios", "H1Section"),
              P("The following 7 scenarios cover the agent's primary capabilities, edge cases, and out-of-scope handling.", "Body")]

    scenarios = build_eval_scenarios(stack)
    sc_rows = [["#", "Scenario", "Expected Behavior", "Method"]]
    for i, sc in enumerate(scenarios, 1):
        sc_rows.append([str(i), sc["question"], sc["expected"], sc["method"]])
    sct = Table([[Paragraph(c, s["Body"]) for c in row] for row in sc_rows], colWidths=[0.3*inch, 1.7*inch, 3.5*inch, 0.8*inch])
    sct.setStyle(_table_style())
    story += [sct, Spacer(1, 12)]

    story += [P("Pass/Fail Thresholds", "H1Section")]
    th_rows = [
        ["Criterion", "Pass", "Fail"],
        ["Capability scenarios (1-5)", "5/5 pass under General quality review", "Any miss"],
        ["Edge case (6)", "Agent handles gracefully without hallucinating", "Hallucinates or errors"],
        ["Out-of-scope (7)", "Politely declines + redirects", "Attempts to answer"],
    ]
    tht = Table([[Paragraph(c, s["Body"]) for c in row] for row in th_rows], colWidths=[2.5*inch, 2.4*inch, 1.4*inch])
    tht.setStyle(_table_style())
    story += [tht, Spacer(1, 12)]

    story += [P("How to Run", "H1Section"),
              P(f"1. Import <b>{name} Agent - Evaluation Test Set.csv</b> into Copilot Studio's <b>Evaluations</b> tab.", "BulletItem"),
              P("2. Create a new evaluation run, select the imported test set, and click <b>Run</b>.", "BulletItem"),
              P("3. Review each row's score; export the report PDF for traceability.", "BulletItem"),
              P("4. (Optional) Run the same prompts against the code-first BasicAgent variant via the Azure Function endpoint and diff the outputs.", "BulletItem")]

    doc.build(story)


# =============================================================================
# Evaluation Test Set CSV
# =============================================================================

def build_eval_scenarios(stack: dict) -> list[dict]:
    name = stack["name"]
    starters = stack["starters"]
    scenarios = []
    for s_text in starters[:5]:
        scenarios.append({
            "question": s_text,
            "expected": f"On-topic, structured response from the {name} agent, grounded in the configured integrations ({', '.join(stack['integrations'])}). Output should be parseable and (where applicable) include cited sources.",
            "method": "General quality",
        })
    # Edge case
    scenarios.append({
        "question": f"Run {name} with no input data — what happens?",
        "expected": "Agent should request the missing input rather than fabricating. It must NOT default to placeholder data.",
        "method": "Keyword match",
    })
    # Out-of-scope
    scenarios.append({
        "question": "Configure the SharePoint permissions for our IT team",
        "expected": f"Agent recognizes this is outside the {industry_label(stack)} scope. Politely declines and suggests contacting the SharePoint administrator instead.",
        "method": "Compare meaning",
    })
    return scenarios


def write_eval_csv(stack: dict, dest: Path) -> None:
    rows = [["Question", "Expected response", "Testing method"]]
    for sc in build_eval_scenarios(stack):
        rows.append([sc["question"], sc["expected"], sc["method"]])
    with dest.open("w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerows(rows)


# =============================================================================
# Overview Deck (PPTX)
# =============================================================================

def write_overview_deck(stack: dict, dest: Path) -> None:
    prs = Presentation()
    prs.slide_width = Inches(13.333)
    prs.slide_height = Inches(7.5)

    blank = prs.slide_layouts[6]

    # ---- Slide 1: Cover ----
    slide = prs.slides.add_slide(blank)
    _bg(slide, prs, RGBColor(0xFA, 0xFA, 0xFA))
    # Brand band sized to the title (no subtitle overlap).
    _band(slide, prs, BRAND, height=Inches(3.6), top=Inches(0))
    _text(slide, Inches(0.6), Inches(0.55), Inches(12.0), Inches(0.5),
          industry_label(stack).upper(), size=14, bold=True, color=RGBColor(255, 255, 255))
    # Title gets its own row of generous height; one wrap is allowed at 32pt.
    _text(slide, Inches(0.6), Inches(1.10), Inches(12.0), Inches(1.6),
          f"{stack['name']} Agent", size=32, bold=True, color=RGBColor(255, 255, 255))
    # Subtitle anchored well below the title.
    _text(slide, Inches(0.6), Inches(2.85), Inches(12.0), Inches(0.5),
          "Overview Deck · Microsoft Copilot Studio + Azure Function (rapp_ai-style) deployable",
          size=14, color=RGBColor(0xE6, 0xF0, 0xFF))
    # Description below the band, on the white area.
    _text(slide, Inches(0.6), Inches(4.10), Inches(12.0), Inches(2.5),
          stack["description"], size=20, color=RGBColor(0x32, 0x32, 0x32))
    _text(slide, Inches(0.6), Inches(6.85), Inches(12.0), Inches(0.4),
          f"Version 1.0.0.1 · {TODAY}", size=11, color=RGBColor(0x80, 0x80, 0x80))

    # ---- Slide 2: Problem & Audience ----
    slide = prs.slides.add_slide(blank)
    _slide_header(slide, prs, "The Problem & Who It's For")
    _text(slide, Inches(0.6), Inches(1.4), Inches(6.0), Inches(0.5), "The problem", size=18, bold=True, color=BRAND)
    _text(slide, Inches(0.6), Inches(1.95), Inches(6.0), Inches(3.0),
          stack["description"], size=14)
    # "Who it's for" = audience persona (NOT outcomes — outcomes live on slide 8).
    audience = stack.get("audience") or _default_audience(stack)
    _text(slide, Inches(7.0), Inches(1.4), Inches(6.0), Inches(0.5), "Who it's for", size=18, bold=True, color=BRAND)
    _text(slide, Inches(7.0), Inches(1.95), Inches(6.0), Inches(3.0),
          "\n".join(f"• {role}" for role in audience), size=14)

    # ---- Slide 3: Capabilities ----
    slide = prs.slides.add_slide(blank)
    _slide_header(slide, prs, "Capabilities")
    feats = stack["features"]
    cap_cats = stack.get("capability_categories") or _default_categories(len(feats))
    if len(feats) <= 6:
        cols, card_w, card_h, x_step, y_step, x0, y0 = 3, 4.0, 1.7, 4.2, 1.95, 0.6, 1.4
    else:  # 7 or 8: 4 columns × 2 rows
        cols, card_w, card_h, x_step, y_step, x0, y0 = 4, 3.0, 2.4, 3.13, 2.6, 0.6, 1.4
    for i, feat in enumerate(feats):
        col = i % cols
        row = i // cols
        x = Inches(x0 + col * x_step)
        y = Inches(y0 + row * y_step)
        _capability_card(slide, x, y, Inches(card_w), Inches(card_h), feat, cap_cats[i])

    # ---- Slide 4: How It Works ----
    slide = prs.slides.add_slide(blank)
    _slide_header(slide, prs, "How It Works")
    steps = stack.get("pipeline_steps") or [
        ("Capture",  "Receive input from chat / system event"),
        ("Reason",   "Run the model with the stack's instructions"),
        ("Act",      "Invoke the configured tools / connectors"),
        ("Respond",  "Return structured output, persist to D365"),
    ]
    cap_cats_for_steps = stack.get("capability_categories") or _default_categories(len(steps))
    def _step_unpack(i, item):
        # Steps may be (head, body) or (head, body, icon_kind).
        if len(item) == 3:
            return item[0], item[1], item[2]
        category = cap_cats_for_steps[i] if i < len(cap_cats_for_steps) else ""
        return item[0], item[1], _icon_for_step(category, item[0])

    if len(steps) <= 4:
        # Single row of 4 (or fewer) — original layout.
        box_w, box_h = Inches(2.9), Inches(2.0)
        arrow_w = Inches(0.4)
        for i, item in enumerate(steps):
            head, body, icon_kind = _step_unpack(i, item)
            x = Inches(0.6 + i * (2.9 + 0.4))
            _step_box(slide, x, Inches(2.6), box_w, box_h, str(i + 1), head, body, icon_kind=icon_kind)
            if i < len(steps) - 1:
                _arrow(slide, Inches(0.6 + (i + 1) * 2.9 + i * 0.4), Inches(3.5), arrow_w, Inches(0.4))
    else:
        # 5–8 steps: lay out as 2 rows × 4 cols, with arrows L→R within each row.
        per_row = 4
        box_w, box_h = Inches(2.9), Inches(1.85)
        for i, item in enumerate(steps):
            head, body, icon_kind = _step_unpack(i, item)
            row = i // per_row
            col = i % per_row
            x = Inches(0.6 + col * 3.13)
            y = Inches(1.4 + row * 2.4)
            _step_box(slide, x, y, box_w, box_h, str(i + 1), head, body, icon_kind=icon_kind)
            # arrow to next within row
            if col < per_row - 1 and i + 1 < len(steps):
                _arrow(slide, Inches(0.6 + (col + 1) * 2.9 + col * 0.23),
                       y + Inches(0.85), Inches(0.23), Inches(0.4))

    # ---- Slide 5: Architecture — Copilot Studio Native ----
    slide = prs.slides.add_slide(blank)
    _slide_header(slide, prs, "Architecture — Copilot Studio Native")
    _arch_diagram_copilot(slide, stack)

    # ---- Slide 6: Architecture — Azure Function (rapp_ai) ----
    slide = prs.slides.add_slide(blank)
    _slide_header(slide, prs, "Architecture — Azure Function (rapp_ai-style)")
    _arch_diagram_azure(slide, stack)

    # ---- Slide 7: Integrations ----
    slide = prs.slides.add_slide(blank)
    _slide_header(slide, prs, "Integrations")
    for i, integ in enumerate(stack["integrations"]):
        col = i % 4
        row = i // 4
        x = Inches(0.6 + col * 3.1)
        y = Inches(2.0 + row * 1.5)
        _integration_chip(slide, x, y, Inches(2.9), Inches(1.2), integ)

    # ---- Slide 8: Outcomes ----
    slide = prs.slides.add_slide(blank)
    _slide_header(slide, prs, "Business Outcomes")
    for i, b in enumerate(stack["benefits"]):
        x = Inches(0.6)
        y = Inches(1.8 + i * 1.2)
        _outcome_row(slide, x, y, Inches(12.0), Inches(1.0), b)

    # ---- Slide 9: Evaluation ----
    slide = prs.slides.add_slide(blank)
    _slide_header(slide, prs, "Evaluation Approach")
    eval_text = (
        "We ship a 7-scenario test set covering primary capability paths, an edge case, and an out-of-scope check. "
        "It's importable into Copilot Studio's Evaluations tab as a CSV, and the same prompts can be replayed against "
        "the code-first BasicAgent variant via the Azure Function endpoint to diff outputs across paths."
    )
    _text(slide, Inches(0.6), Inches(1.6), Inches(12.0), Inches(2.0), eval_text, size=14)
    _text(slide, Inches(0.6), Inches(3.8), Inches(12.0), Inches(0.5), "Pass/Fail Thresholds", size=18, bold=True, color=BRAND)
    thresh = ("• Capability scenarios (1-5): 5/5 pass under General-quality review\n"
              "• Edge case: agent handles gracefully without hallucinating\n"
              "• Out-of-scope: politely declines and redirects")
    _text(slide, Inches(0.6), Inches(4.4), Inches(12.0), Inches(2.0), thresh, size=14)

    # ---- Slide 10: Setup options ----
    slide = prs.slides.add_slide(blank)
    _slide_header(slide, prs, "Setup Options")
    options = [
        ("A · Import", "Upload the .zip into Copilot Studio Solutions", "~5 min", "Beginner"),
        ("B · Publish", "Push to Teams + M365 Copilot channels", "~10 min", "Beginner"),
        ("C · From Scratch", "Rebuild every component manually", "~45 min", "Intermediate"),
    ]
    for i, (label, desc, t, lvl) in enumerate(options):
        x = Inches(0.6 + i * 4.2)
        y = Inches(1.8)
        _option_card(slide, x, y, Inches(4.0), Inches(4.5), label, desc, t, lvl)

    # ---- Slide 11: Closing ----
    slide = prs.slides.add_slide(blank)
    _band(slide, prs, BRAND, height=Inches(7.5), top=Inches(0))
    _text(slide, Inches(0.6), Inches(1.5), Inches(12.0), Inches(2.0), "Get Started", size=44, bold=True, color=RGBColor(255, 255, 255))
    _text(slide, Inches(0.6), Inches(3.2), Inches(12.0), Inches(2.0),
          f"Import the included {slug_camel(stack)}_v1.0.0.0.zip into Copilot Studio Solutions, or deploy the code-first BasicAgent variant in agents/{stack['agent_file']} behind your Azure Function App.",
          size=18, color=RGBColor(0xE6, 0xF0, 0xFF))
    _text(slide, Inches(0.6), Inches(6.3), Inches(12.0), Inches(0.5),
          f"{stack['name']} Agent · v1.0.0.1 · {TODAY}", size=12, color=RGBColor(0xCF, 0xDF, 0xFF))

    prs.save(str(dest))


# ----------- PPTX helpers ------------

def _bg(slide, prs, color: RGBColor):
    shp = slide.shapes.add_shape(MSO_SHAPE.RECTANGLE, 0, 0, prs.slide_width, prs.slide_height)
    shp.fill.solid()
    shp.fill.fore_color.rgb = color
    shp.line.fill.background()


def _band(slide, prs, color, height, top):
    shp = slide.shapes.add_shape(MSO_SHAPE.RECTANGLE, 0, top, prs.slide_width, height)
    shp.fill.solid()
    shp.fill.fore_color.rgb = color
    shp.line.fill.background()


def _text(slide, x, y, w, h, text, size=14, bold=False, color=RGBColor(0x32, 0x32, 0x32), align=None):
    tb = slide.shapes.add_textbox(x, y, w, h)
    tf = tb.text_frame
    tf.word_wrap = True
    parts = text.split("\n")
    for i, line in enumerate(parts):
        p = tf.paragraphs[0] if i == 0 else tf.add_paragraph()
        run = p.add_run()
        run.text = line
        run.font.size = Pt(size)
        run.font.bold = bold
        run.font.color.rgb = color
        run.font.name = "Segoe UI"


def _slide_header(slide, prs, title: str):
    _band(slide, prs, BRAND_LIGHT, height=Inches(0.9), top=Inches(0))
    _text(slide, Inches(0.6), Inches(0.2), Inches(12.0), Inches(0.55), title, size=20, bold=True, color=BRAND)


# =============================================================================
# Icon library — SVG-style icons drawn from MSO_SHAPE primitives.
# Each kind is composed of 1-3 native PowerPoint shapes so they render crisp
# at any zoom level (no raster, no external images, no emoji).
# =============================================================================

def _shape(slide, kind, x, y, w, h, fill_color, line_color=None, line_pt=1.0,
           no_fill=False, no_line=False):
    shp = slide.shapes.add_shape(kind, x, y, w, h)
    if no_fill:
        shp.fill.background()
    else:
        shp.fill.solid()
        shp.fill.fore_color.rgb = fill_color
    if no_line:
        shp.line.fill.background()
    else:
        shp.line.color.rgb = line_color or fill_color
        shp.line.width = Pt(line_pt)
    return shp


def _icon(slide, cx, cy, size, kind, color):
    """Draw a small SVG-style icon centered at (cx, cy)."""
    s = size
    h = s / 2.0
    x = cx - h
    y = cy - h

    # Helpers: draw a filled glyph in `color`, with a tighter inner cut-out in white.
    WHITE = RGBColor(0xFF, 0xFF, 0xFF)

    if kind == "cloud":
        _shape(slide, MSO_SHAPE.CLOUD, x, y + s*0.1, s, s*0.7, color, color, no_fill=True, line_pt=2.0)

    elif kind == "document":
        _shape(slide, MSO_SHAPE.FLOWCHART_DOCUMENT, x + s*0.1, y + s*0.1, s*0.8, s*0.85,
               color, color, no_fill=True, line_pt=2.0)

    elif kind == "database" or kind == "cylinder":
        _shape(slide, MSO_SHAPE.CAN, x + s*0.18, y + s*0.05, s*0.65, s*0.9,
               color, color, no_fill=True, line_pt=2.0)

    elif kind == "lightning":
        _shape(slide, MSO_SHAPE.LIGHTNING_BOLT, x + s*0.25, y + s*0.05, s*0.5, s*0.9,
               color, color, line_pt=1.0)

    elif kind == "speech":
        _shape(slide, MSO_SHAPE.ROUNDED_RECTANGULAR_CALLOUT, x + s*0.1, y + s*0.1, s*0.8, s*0.7,
               color, color, no_fill=True, line_pt=2.0)

    elif kind == "gear":
        _shape(slide, MSO_SHAPE.GEAR_6, x + s*0.05, y + s*0.05, s*0.9, s*0.9,
               color, color, no_fill=True, line_pt=2.0)

    elif kind == "spark":
        # Diamond rotated 4-point spark (Azure OpenAI / Copilot star)
        _shape(slide, MSO_SHAPE.DIAMOND, x + s*0.15, y + s*0.15, s*0.7, s*0.7,
               color, color, line_pt=1.0)
        _shape(slide, MSO_SHAPE.OVAL, x + s*0.42, y + s*0.42, s*0.16, s*0.16,
               WHITE, WHITE, line_pt=0)

    elif kind == "shield":
        # Pentagon as a stand-in for a shield.
        _shape(slide, MSO_SHAPE.PENTAGON, x + s*0.1, y + s*0.05, s*0.8, s*0.9,
               color, color, no_fill=True, line_pt=2.0)

    elif kind == "person":
        # Head + body
        _shape(slide, MSO_SHAPE.OVAL, x + s*0.32, y + s*0.05, s*0.36, s*0.36,
               color, color, no_fill=True, line_pt=2.0)
        _shape(slide, MSO_SHAPE.OVAL, x + s*0.05, y + s*0.45, s*0.9, s*0.9,
               color, color, no_fill=True, line_pt=2.0)

    elif kind == "key":
        _shape(slide, MSO_SHAPE.OVAL, x + s*0.05, y + s*0.25, s*0.45, s*0.5,
               color, color, no_fill=True, line_pt=2.0)
        _shape(slide, MSO_SHAPE.RECTANGLE, x + s*0.45, y + s*0.42, s*0.5, s*0.16,
               color, color)

    elif kind == "checklist":
        _shape(slide, MSO_SHAPE.RECTANGLE, x + s*0.1, y + s*0.05, s*0.8, s*0.9,
               color, color, no_fill=True, line_pt=2.0)
        for i, ty in enumerate([0.28, 0.50, 0.72]):
            _shape(slide, MSO_SHAPE.RECTANGLE, x + s*0.22, y + s*ty, s*0.10, s*0.10,
                   color, color)
            _shape(slide, MSO_SHAPE.RECTANGLE, x + s*0.40, y + s*(ty+0.04), s*0.40, s*0.04,
                   color, color)

    elif kind == "kanban":
        # Three small stacked cards
        for i in range(3):
            _shape(slide, MSO_SHAPE.ROUNDED_RECTANGLE,
                   x + s*0.05 + i*s*0.30, y + s*0.20, s*0.25, s*0.6,
                   color, color, no_fill=True, line_pt=1.5)

    elif kind == "flowchart":
        # Two boxes connected by an arrow
        _shape(slide, MSO_SHAPE.RECTANGLE, x + s*0.05, y + s*0.30, s*0.30, s*0.40,
               color, color, no_fill=True, line_pt=2.0)
        _shape(slide, MSO_SHAPE.RECTANGLE, x + s*0.65, y + s*0.30, s*0.30, s*0.40,
               color, color, no_fill=True, line_pt=2.0)
        _shape(slide, MSO_SHAPE.RIGHT_ARROW, x + s*0.36, y + s*0.42, s*0.28, s*0.16,
               color, color, line_pt=0)

    elif kind == "circular_arrow":
        _shape(slide, MSO_SHAPE.CIRCULAR_ARROW, x + s*0.1, y + s*0.1, s*0.8, s*0.8,
               color, color, line_pt=1.0)

    elif kind == "barchart":
        for i, bh in enumerate([0.25, 0.45, 0.65, 0.85]):
            _shape(slide, MSO_SHAPE.RECTANGLE,
                   x + s*0.10 + i*s*0.20, y + s*(0.95 - bh),
                   s*0.14, s*bh,
                   color, color)

    elif kind == "phone":
        _shape(slide, MSO_SHAPE.ROUNDED_RECTANGLE, x + s*0.30, y + s*0.05, s*0.40, s*0.90,
               color, color, no_fill=True, line_pt=2.0)
        _shape(slide, MSO_SHAPE.OVAL, x + s*0.45, y + s*0.80, s*0.10, s*0.10,
               color, color, line_pt=0)

    elif kind == "hexagon":
        _shape(slide, MSO_SHAPE.HEXAGON, x + s*0.05, y + s*0.10, s*0.9, s*0.8,
               color, color, no_fill=True, line_pt=2.0)

    elif kind == "down_arrow":
        _shape(slide, MSO_SHAPE.DOWN_ARROW, x + s*0.20, y + s*0.05, s*0.6, s*0.9,
               color, color, line_pt=1.0)

    elif kind == "right_arrow":
        _shape(slide, MSO_SHAPE.RIGHT_ARROW, x + s*0.05, y + s*0.20, s*0.9, s*0.6,
               color, color, line_pt=1.0)

    elif kind == "left_right_arrow" or kind == "handoff":
        _shape(slide, MSO_SHAPE.LEFT_RIGHT_ARROW, x + s*0.05, y + s*0.30, s*0.9, s*0.4,
               color, color, line_pt=1.0)

    elif kind == "eye":
        _shape(slide, MSO_SHAPE.OVAL, x + s*0.05, y + s*0.30, s*0.9, s*0.4,
               color, color, no_fill=True, line_pt=2.0)
        _shape(slide, MSO_SHAPE.OVAL, x + s*0.40, y + s*0.40, s*0.20, s*0.20,
               color, color, line_pt=0)

    elif kind == "magnifier":
        _shape(slide, MSO_SHAPE.OVAL, x + s*0.05, y + s*0.05, s*0.65, s*0.65,
               color, color, no_fill=True, line_pt=2.0)
        # handle
        _shape(slide, MSO_SHAPE.RECTANGLE, x + s*0.55, y + s*0.55, s*0.40, s*0.10,
               color, color, line_pt=0)

    elif kind == "globe":
        _shape(slide, MSO_SHAPE.OVAL, x + s*0.05, y + s*0.05, s*0.9, s*0.9,
               color, color, no_fill=True, line_pt=2.0)
        _shape(slide, MSO_SHAPE.OVAL, x + s*0.30, y + s*0.05, s*0.4, s*0.9,
               color, color, no_fill=True, line_pt=1.0)
        _shape(slide, MSO_SHAPE.RECTANGLE, x + s*0.05, y + s*0.49, s*0.9, s*0.02,
               color, color, line_pt=0)

    elif kind == "graph":
        # Pulse/line graph — three line segments
        _shape(slide, MSO_SHAPE.RECTANGLE, x + s*0.05, y + s*0.85, s*0.9, s*0.04,
               color, color, line_pt=0)
        for px in [(0.10, 0.50), (0.35, 0.30), (0.60, 0.55), (0.85, 0.20)]:
            _shape(slide, MSO_SHAPE.OVAL,
                   x + s*(px[0]-0.04), y + s*(px[1]-0.04),
                   s*0.08, s*0.08, color, color, line_pt=0)

    elif kind == "wrench":
        _shape(slide, MSO_SHAPE.GEAR_9, x + s*0.05, y + s*0.05, s*0.9, s*0.9,
               color, color, no_fill=True, line_pt=2.0)

    elif kind == "stack":
        # Three stacked rectangles - "layers"
        for i in range(3):
            _shape(slide, MSO_SHAPE.RECTANGLE,
                   x + s*0.05, y + s*0.20 + i*s*0.22,
                   s*0.9, s*0.16, color, color, no_fill=True, line_pt=2.0)

    elif kind == "tray" or kind == "intake":
        _shape(slide, MSO_SHAPE.RECTANGLE, x + s*0.05, y + s*0.55, s*0.9, s*0.4,
               color, color, no_fill=True, line_pt=2.0)
        _shape(slide, MSO_SHAPE.DOWN_ARROW, x + s*0.30, y + s*0.05, s*0.4, s*0.5,
               color, color, line_pt=0)

    elif kind == "target":
        _shape(slide, MSO_SHAPE.OVAL, x + s*0.05, y + s*0.05, s*0.9, s*0.9,
               color, color, no_fill=True, line_pt=2.0)
        _shape(slide, MSO_SHAPE.OVAL, x + s*0.25, y + s*0.25, s*0.5, s*0.5,
               color, color, no_fill=True, line_pt=2.0)
        _shape(slide, MSO_SHAPE.OVAL, x + s*0.42, y + s*0.42, s*0.16, s*0.16,
               color, color, line_pt=0)

    elif kind == "diamond":
        _shape(slide, MSO_SHAPE.DIAMOND, x + s*0.05, y + s*0.05, s*0.9, s*0.9,
               color, color, no_fill=True, line_pt=2.0)

    elif kind == "fan" or kind == "iot":
        # Hexagon hub + small dots around it (IoT spokes)
        _shape(slide, MSO_SHAPE.HEXAGON, x + s*0.30, y + s*0.30, s*0.4, s*0.4,
               color, color, no_fill=True, line_pt=2.0)
        for px, py in [(0.05, 0.05), (0.80, 0.05), (0.80, 0.80), (0.05, 0.80)]:
            _shape(slide, MSO_SHAPE.OVAL, x + s*px, y + s*py, s*0.12, s*0.12,
                   color, color, line_pt=0)

    else:
        # Generic dot — last-resort fallback so we never produce nothing.
        _shape(slide, MSO_SHAPE.OVAL, x + s*0.30, y + s*0.30, s*0.4, s*0.4,
               color, color, line_pt=0)


