def _icon_for_integration(label: str) -> str:
    low = label.lower()
    for needle, kind in INTEGRATION_ICON_MAP.items():
        if needle in low:
            return kind
    return "diamond"


def _icon_for_step(category: str, name: str) -> str:
    cat = (category or "").strip().lower()
    if cat in STEP_CATEGORY_ICON:
        return STEP_CATEGORY_ICON[cat]
    nm = (name or "").lower()
    for needle, kind in STEP_CATEGORY_ICON.items():
        if needle in nm:
            return kind
    return "right_arrow"


# =============================================================================
# Card / chip / step helpers (now icon-aware)
# =============================================================================

def _capability_card(slide, x, y, w, h, title, sub):
    shp = slide.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE, x, y, w, h)
    shp.fill.solid()
    shp.fill.fore_color.rgb = RGBColor(0xFF, 0xFF, 0xFF)
    shp.line.color.rgb = RGBColor(0xE0, 0xE0, 0xE0)
    # Top-right icon based on the category sub-label.
    icon_kind = _icon_for_step(sub, title)
    icon_size = Inches(0.45)
    _icon(slide, x + w - Inches(0.40), y + Inches(0.40), icon_size, icon_kind, BRAND)
    _text(slide, x + Inches(0.2), y + Inches(0.15), w - Inches(0.95), Inches(0.4), sub, size=10, color=BRAND)
    _text(slide, x + Inches(0.2), y + Inches(0.55), w - Inches(0.4), Inches(0.9), title, size=14, bold=True)


def _step_box(slide, x, y, w, h, num, head, body, icon_kind=None):
    shp = slide.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE, x, y, w, h)
    shp.fill.solid()
    shp.fill.fore_color.rgb = RGBColor(0xFF, 0xFF, 0xFF)
    shp.line.color.rgb = BRAND
    shp.line.width = Pt(1.5)
    _text(slide, x + Inches(0.2), y + Inches(0.10), Inches(0.6), Inches(0.45), num, size=18, bold=True, color=BRAND)
    if icon_kind:
        _icon(slide, x + w - Inches(0.32), y + Inches(0.32), Inches(0.45), icon_kind, BRAND)
    _text(slide, x + Inches(0.2), y + Inches(0.65), w - Inches(0.4), Inches(0.5), head, size=13, bold=True)
    _text(slide, x + Inches(0.2), y + Inches(1.10), w - Inches(0.4), Inches(0.7), body, size=10, color=RGBColor(0x55, 0x55, 0x55))


def _arrow(slide, x, y, w, h):
    shp = slide.shapes.add_shape(MSO_SHAPE.RIGHT_ARROW, x, y, w, h)
    shp.fill.solid()
    shp.fill.fore_color.rgb = BRAND
    shp.line.fill.background()


def _integration_chip(slide, x, y, w, h, label):
    shp = slide.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE, x, y, w, h)
    shp.fill.solid()
    shp.fill.fore_color.rgb = BRAND_LIGHT
    shp.line.color.rgb = BRAND
    icon_kind = _icon_for_integration(label)
    _icon(slide, x + Inches(0.40), y + h/2, Inches(0.50), icon_kind, BRAND_DARK)
    _text(slide, x + Inches(0.80), y + Inches(0.30), w - Inches(0.95), Inches(0.6),
          label, size=14, bold=True, color=BRAND_DARK)


def _outcome_row(slide, x, y, w, h, body):
    shp = slide.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE, x, y, w, h)
    shp.fill.solid()
    shp.fill.fore_color.rgb = RGBColor(0xFF, 0xFF, 0xFF)
    shp.line.color.rgb = ACCENT
    bullet = slide.shapes.add_shape(MSO_SHAPE.OVAL, x + Inches(0.25), y + Inches(0.3), Inches(0.4), Inches(0.4))
    bullet.fill.solid()
    bullet.fill.fore_color.rgb = ACCENT
    bullet.line.fill.background()
    _text(slide, x + Inches(0.85), y + Inches(0.25), w - Inches(1.0), Inches(0.6), body, size=16, color=RGBColor(0x32, 0x32, 0x32))


def _option_card(slide, x, y, w, h, label, desc, time, level):
    shp = slide.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE, x, y, w, h)
    shp.fill.solid()
    shp.fill.fore_color.rgb = RGBColor(0xFF, 0xFF, 0xFF)
    shp.line.color.rgb = BRAND
    shp.line.width = Pt(1.5)
    _text(slide, x + Inches(0.3), y + Inches(0.3), w - Inches(0.6), Inches(0.7), label, size=20, bold=True, color=BRAND)
    _text(slide, x + Inches(0.3), y + Inches(1.1), w - Inches(0.6), Inches(2.0), desc, size=13, color=RGBColor(0x44, 0x44, 0x44))
    _text(slide, x + Inches(0.3), y + Inches(3.2), w - Inches(0.6), Inches(0.5), f"⏱  {time}", size=13, bold=True)
    _text(slide, x + Inches(0.3), y + Inches(3.7), w - Inches(0.6), Inches(0.5), f"🎯  {level}", size=13, bold=True)


def _default_audience(stack: dict) -> list[str]:
    """Persona roster for slide 2 when an `audience` key isn't supplied."""
    industry_personas = {
        "energy_utilities":    ["Reliability engineers", "Asset managers", "Field service supervisors", "Capex / investment planners"],
        "manufacturing":       ["Plant reliability leads", "Maintenance planners", "Quality engineers", "Operations managers"],
        "professional_services": ["Solution architects", "Engagement leads", "Pre-sales SAs", "Delivery managers"],
        "healthcare":          ["Care coordinators", "Member services", "Clinical operations leads", "Compliance officers"],
        "b2b_sales":           ["Account executives", "Sales managers", "RevOps leads", "Solution consultants"],
        "slg_government":      ["Programme managers", "Policy analysts", "Compliance officers", "Citizen-services leads"],
        "financial_services":  ["Finance operations leads", "AP/AR managers", "Risk and compliance officers", "Frontline service leads"],
        "b2c_sales":           ["Customer experience leads", "Frontline managers", "Knowledge managers"],
        "media":               ["Editors", "Reporters", "Digital ops leads"],
        "software_dp":         ["Product managers", "Engineering leads", "Platform owners"],
        "general":             ["Operations leads", "Knowledge workers", "Process owners"],
    }
    return industry_personas.get(stack["industry"], industry_personas["general"])


def _default_categories(n: int) -> list[str]:
    """Capability category labels — replaces generic 'Capability N' subheads.

    For 8-step process flows we use the canonical agentic verbs; otherwise
    we fall back to broad lifecycle phases that read naturally on cards.
    """
    if n == 8:
        return ["Sense", "Detect", "Predict", "Decide",
                "Plan", "Execute", "Persist", "Optimise"]
    if n == 7:
        return ["Sense", "Detect", "Decide", "Plan", "Execute", "Persist", "Optimise"]
    if n == 6:
        return ["Capture", "Reason", "Decide", "Act", "Persist", "Improve"]
    if n == 5:
        return ["Capture", "Reason", "Act", "Persist", "Improve"]
    if n == 4:
        return ["Capture", "Reason", "Act", "Respond"]
    return [f"Step {i+1}" for i in range(n)]


def _zone(slide, x, y, w, h, label, color_fill, color_border):
    """Draw a labelled WAF zone — light-tinted rounded rectangle with a header strip."""
    shp = slide.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE, x, y, w, h)
    shp.fill.solid()
    shp.fill.fore_color.rgb = color_fill
    shp.line.color.rgb = color_border
    shp.line.width = Pt(1.0)
    _text(slide, x + Inches(0.15), y + Inches(0.06), w - Inches(0.3), Inches(0.3),
          label, size=10, bold=True, color=color_border)


