def _icon_for_node(head: str) -> str:
    low = (head or "").lower()
    for needle, kind in _NODE_ICON_MAP.items():
        if needle in low:
            return kind
    return "diamond"


def _node(slide, x, y, w, h, head, sub, fill, stroke, head_color, icon_kind=None):
    """Single architecture node — rounded rectangle with two-line label + icon."""
    shp = slide.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE, x, y, w, h)
    shp.fill.solid()
    shp.fill.fore_color.rgb = fill
    shp.line.color.rgb = stroke
    shp.line.width = Pt(1.25)
    icon_size = Inches(0.32)
    icon_pad  = Inches(0.10)
    icon_kind = icon_kind or _icon_for_node(head)
    # Icon top-left, label shifted right.
    _icon(slide, x + icon_pad + icon_size/2, y + icon_pad + icon_size/2,
          icon_size, icon_kind, stroke)
    label_x = x + icon_pad + icon_size + Inches(0.08)
    _text(slide, label_x, y + Inches(0.08), w - (label_x - x) - Inches(0.05), Inches(0.32),
          head, size=11, bold=True, color=head_color)
    _text(slide, x + Inches(0.1), y + Inches(0.4), w - Inches(0.2), h - Inches(0.45),
          sub, size=9, color=RGBColor(0x55, 0x55, 0x55))


def _connector(slide, x1, y1, x2, y2, color=None):
    """Thin colored connector line between two points."""
    color = color or BRAND
    line = slide.shapes.add_connector(1, x1, y1, x2, y2)  # 1 = STRAIGHT
    line.line.color.rgb = color
    line.line.width = Pt(1.5)


def _waf_legend(slide, top):
    """Five-pillar legend strip at the bottom of an architecture slide."""
    pillars = [
        ("Reliability",            RGBColor(0x00, 0x78, 0xD4)),
        ("Security",               RGBColor(0x5C, 0x2D, 0x91)),
        ("Cost Optimization",      RGBColor(0x00, 0x82, 0x72)),
        ("Operational Excellence", RGBColor(0xCA, 0x50, 0x10)),
        ("Performance Efficiency", RGBColor(0x10, 0x6E, 0xBE)),
    ]
    pad = 0.15
    pill_w = (13.333 - 1.2 - pad * (len(pillars) - 1)) / len(pillars)
    for i, (label, color) in enumerate(pillars):
        x = Inches(0.6 + i * (pill_w + pad))
        shp = slide.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE, x, top, Inches(pill_w), Inches(0.45))
        shp.fill.solid()
        shp.fill.fore_color.rgb = RGBColor(0xFA, 0xFA, 0xFA)
        shp.line.color.rgb = color
        shp.line.width = Pt(1.25)
        _text(slide, x, top + Inches(0.1), Inches(pill_w), Inches(0.3),
              label, size=11, bold=True, color=color)


def _arch_diagram_copilot(slide, stack):
    """WAF-styled Copilot Studio architecture: zones, connectors, brand palette, pillar legend."""
    fill_blue, line_blue   = RGBColor(0xE6, 0xF0, 0xFA), RGBColor(0x00, 0x78, 0xD4)
    fill_pur,  line_pur    = RGBColor(0xF0, 0xE6, 0xF8), RGBColor(0x5C, 0x2D, 0x91)
    fill_acc,  line_acc    = RGBColor(0xDE, 0xEC, 0xF9), RGBColor(0x10, 0x6E, 0xBE)
    fill_teal, line_teal   = RGBColor(0xE0, 0xF4, 0xF1), RGBColor(0x00, 0x82, 0x72)
    fill_zone_id           = RGBColor(0xFA, 0xF6, 0xFF)
    fill_zone_pp           = RGBColor(0xF6, 0xFA, 0xFF)
    fill_zone_az           = RGBColor(0xF2, 0xF8, 0xFF)
    fill_zone_sor          = RGBColor(0xF1, 0xFA, 0xF7)

    # Zones
    _zone(slide, Inches(0.4), Inches(1.05), Inches(2.7), Inches(4.2), "USER + IDENTITY",     fill_zone_id, line_pur)
    _zone(slide, Inches(3.3), Inches(1.05), Inches(4.0), Inches(4.2), "POWER PLATFORM",      fill_zone_pp, line_acc)
    _zone(slide, Inches(7.5), Inches(1.05), Inches(2.8), Inches(4.2), "AZURE WORKLOAD",      fill_zone_az, line_blue)
    _zone(slide, Inches(10.5), Inches(1.05), Inches(2.4), Inches(4.2), "SYSTEMS OF RECORD",  fill_zone_sor, line_teal)

    # User + identity
    _node(slide, Inches(0.55), Inches(1.45), Inches(2.4), Inches(0.95), "End User", "Teams / M365 Copilot Chat", fill_blue, line_blue, RGBColor(0x00, 0x20, 0x50))
    _node(slide, Inches(0.55), Inches(2.55), Inches(2.4), Inches(0.95), "Microsoft Entra ID", "Delegated · Conditional Access", fill_pur, line_pur, RGBColor(0x2E, 0x1A, 0x47))
    _node(slide, Inches(0.55), Inches(3.65), Inches(2.4), Inches(0.95), "Microsoft Purview", "DLP · Sensitivity · Audit",      fill_pur, line_pur, RGBColor(0x2E, 0x1A, 0x47))

    # Power Platform
    _node(slide, Inches(3.45), Inches(1.45), Inches(3.7), Inches(0.95), "Copilot Studio Agent",          "Topics · Generative orchestration", fill_acc,  line_acc, RGBColor(0x00, 0x20, 0x50))
    _node(slide, Inches(3.45), Inches(2.55), Inches(3.7), Inches(0.95), "Custom Action",                 stack["agent_class"],                 fill_acc,  line_acc, RGBColor(0x00, 0x20, 0x50))
    _node(slide, Inches(3.45), Inches(3.65), Inches(3.7), Inches(0.95), "Power Automate Flow",           "HTTP wrapper · Retry · Dead-letter", fill_acc,  line_acc, RGBColor(0x00, 0x20, 0x50))
    _node(slide, Inches(3.45), Inches(4.75), Inches(3.7), Inches(0.45), "Dataverse — state · memory · audit", "", fill_acc, line_acc, RGBColor(0x00, 0x20, 0x50))

    # Azure workload
    _node(slide, Inches(7.65), Inches(1.45), Inches(2.5), Inches(0.95), "API Management",  "Throttle · Cache · WAF",          fill_blue, line_blue, RGBColor(0x00, 0x20, 0x50))
    _node(slide, Inches(7.65), Inches(2.55), Inches(2.5), Inches(0.95), "Azure Functions", "predictive_asset_maintenance · MI", fill_blue, line_blue, RGBColor(0x00, 0x20, 0x50))
    _node(slide, Inches(7.65), Inches(3.65), Inches(2.5), Inches(0.95), "Azure OpenAI / ML / IoT", "Reasoning · Models · Telemetry", fill_blue, line_blue, RGBColor(0x00, 0x20, 0x50))
    _node(slide, Inches(7.65), Inches(4.75), Inches(2.5), Inches(0.45), "Key Vault · App Insights · LAW", "", fill_blue, line_blue, RGBColor(0x00, 0x20, 0x50))

    # Systems of Record
    integ_rows = stack["integrations"][:4]
    while len(integ_rows) < 4:
        integ_rows.append("—")
    for i, label in enumerate(integ_rows):
        _node(slide, Inches(10.65), Inches(1.45 + i * 1.1), Inches(2.1), Inches(0.95),
              label, "", fill_teal, line_teal, RGBColor(0x00, 0x3D, 0x33))

    # Connectors (left → right horizontal flow)
    _connector(slide, Inches(2.95), Inches(1.93), Inches(3.45), Inches(1.93), color=line_pur)
    _connector(slide, Inches(7.15), Inches(2.93), Inches(7.65), Inches(2.93), color=line_acc)
    _connector(slide, Inches(10.15), Inches(3.03), Inches(10.65), Inches(3.03), color=line_blue)

    # WAF pillar legend
    _waf_legend(slide, Inches(5.75))


def _arch_diagram_azure(slide, stack):
    """WAF-styled Azure Function architecture: zoned VNet topology + observability + SoR."""
    fill_blue, line_blue   = RGBColor(0xE6, 0xF0, 0xFA), RGBColor(0x00, 0x78, 0xD4)
    fill_pur,  line_pur    = RGBColor(0xF0, 0xE6, 0xF8), RGBColor(0x5C, 0x2D, 0x91)
    fill_acc,  line_acc    = RGBColor(0xDE, 0xEC, 0xF9), RGBColor(0x10, 0x6E, 0xBE)
    fill_teal, line_teal   = RGBColor(0xE0, 0xF4, 0xF1), RGBColor(0x00, 0x82, 0x72)
    fill_amber, line_amber = RGBColor(0xFF, 0xF4, 0xE0), RGBColor(0xCA, 0x50, 0x10)
    fill_gray, line_gray   = RGBColor(0xF3, 0xF2, 0xF1), RGBColor(0x60, 0x5E, 0x5C)
    fill_zone_edge         = RGBColor(0xFA, 0xF6, 0xFF)
    fill_zone_spoke        = RGBColor(0xF2, 0xF8, 0xFF)
    fill_zone_obs          = RGBColor(0xFF, 0xFA, 0xF2)
    fill_zone_sor          = RGBColor(0xF1, 0xFA, 0xF7)

    _zone(slide, Inches(0.4),  Inches(1.05), Inches(2.7), Inches(4.2), "EDGE + IDENTITY",   fill_zone_edge, line_pur)
    _zone(slide, Inches(3.3),  Inches(1.05), Inches(4.7), Inches(4.2), "AZURE SPOKE VNET",  fill_zone_spoke, line_blue)
    _zone(slide, Inches(8.2),  Inches(1.05), Inches(2.5), Inches(4.2), "OBSERVABILITY",     fill_zone_obs, line_amber)
    _zone(slide, Inches(10.9), Inches(1.05), Inches(2.0), Inches(4.2), "SYSTEMS OF RECORD", fill_zone_sor, line_teal)

    # Edge + identity
    _node(slide, Inches(0.55), Inches(1.45), Inches(2.4), Inches(0.95), "Caller", "Teams · Web · Power Automate", fill_blue, line_blue, RGBColor(0x00, 0x20, 0x50))
    _node(slide, Inches(0.55), Inches(2.55), Inches(2.4), Inches(0.95), "Azure Front Door", "Anycast · WAF · TLS", fill_acc, line_acc, RGBColor(0x00, 0x20, 0x50))
    _node(slide, Inches(0.55), Inches(3.65), Inches(2.4), Inches(0.95), "Microsoft Entra ID", "Easy Auth · Managed Identity", fill_pur, line_pur, RGBColor(0x2E, 0x1A, 0x47))

    # Spoke VNet — App / Data / Persist / Sec sub-tiers
    _node(slide, Inches(3.45), Inches(1.45), Inches(2.2), Inches(0.95), "API Management",  "Standard v2 · OAuth", fill_acc,  line_acc,  RGBColor(0x00, 0x20, 0x50))
    _node(slide, Inches(3.45), Inches(2.55), Inches(2.2), Inches(0.95), "Azure Functions", "Premium EP1 · Py 3.11 · ZRS", fill_blue, line_blue, RGBColor(0x00, 0x20, 0x50))
    _node(slide, Inches(3.45), Inches(3.65), Inches(2.2), Inches(0.95), "Key Vault",       "RBAC · CMK · Soft-delete", fill_pur,  line_pur,  RGBColor(0x2E, 0x1A, 0x47))
    _node(slide, Inches(5.85), Inches(1.45), Inches(2.0), Inches(0.95), "Azure OpenAI",    "gpt-4o · PTU · CMK", fill_blue, line_blue, RGBColor(0x00, 0x20, 0x50))
    _node(slide, Inches(5.85), Inches(2.55), Inches(2.0), Inches(0.95), "Azure ML + IoT",  "Anomaly · RUL · DPS", fill_blue, line_blue, RGBColor(0x00, 0x20, 0x50))
    _node(slide, Inches(5.85), Inches(3.65), Inches(2.0), Inches(0.95), "Dataverse / Cosmos", "State · Sessions · Blob", fill_gray, line_gray, RGBColor(0x25, 0x24, 0x23))
    _node(slide, Inches(3.45), Inches(4.75), Inches(4.4), Inches(0.45), "Defender for Cloud — CSPM · CWPP", "", fill_pur, line_pur, RGBColor(0x2E, 0x1A, 0x47))

    # Observability column
    _node(slide, Inches(8.3),  Inches(1.45), Inches(2.3), Inches(0.95), "Application Insights", "Distributed tracing", fill_amber, line_amber, RGBColor(0x4E, 0x1F, 0x00))
    _node(slide, Inches(8.3),  Inches(2.55), Inches(2.3), Inches(0.95), "Log Analytics",        "KQL · Workbooks", fill_amber, line_amber, RGBColor(0x4E, 0x1F, 0x00))
    _node(slide, Inches(8.3),  Inches(3.65), Inches(2.3), Inches(0.95), "Azure Monitor",        "Alerts · Action Groups", fill_amber, line_amber, RGBColor(0x4E, 0x1F, 0x00))

    # Systems of Record
    integ_rows = stack["integrations"][:4]
    while len(integ_rows) < 4:
        integ_rows.append("—")
    for i, label in enumerate(integ_rows):
        _node(slide, Inches(11.0), Inches(1.45 + i * 1.1), Inches(1.7), Inches(0.95),
              label, "", fill_teal, line_teal, RGBColor(0x00, 0x3D, 0x33))

    # Connectors — flow tracing
    _connector(slide, Inches(2.95), Inches(2.93), Inches(3.45), Inches(2.93), color=line_acc)   # Identity → APIM line representative
    _connector(slide, Inches(5.65), Inches(2.93), Inches(5.85), Inches(2.93), color=line_blue)  # Functions → AI tier
    _connector(slide, Inches(7.85), Inches(2.93), Inches(8.30), Inches(2.93), color=line_amber) # Functions → Observability
    _connector(slide, Inches(7.85), Inches(1.93), Inches(11.0), Inches(1.93), color=line_teal)  # Functions → SoR (top integration)

    _waf_legend(slide, Inches(5.75))


# =============================================================================
# Icon PNG (256x256, branded)
# =============================================================================

_FONT_CANDIDATES = [
    "/System/Library/Fonts/Supplemental/Arial Bold.ttf",
    "/System/Library/Fonts/Helvetica.ttc",
    "/System/Library/Fonts/SFNS.ttf",
    "/Library/Fonts/Arial.ttf",
]


def _load_font(size: int):
    for path in _FONT_CANDIDATES:
        if os.path.exists(path):
            try:
                return ImageFont.truetype(path, size)
            except Exception:
                continue
    return ImageFont.load_default()


def write_icon_png(stack: dict, dest: Path) -> None:
    size = 512
    img = Image.new("RGBA", (size, size), (255, 255, 255, 0))
    draw = ImageDraw.Draw(img)
    # rounded background
    draw.rounded_rectangle((0, 0, size - 1, size - 1), radius=80, fill=(0x1F, 0x4E, 0xD8, 255))
    # initials
    initials = "".join([w[0] for w in re.split(r"[\s\-]+", stack["name"]) if w][:2]).upper() or "AI"
    font = _load_font(220)
    bbox = draw.textbbox((0, 0), initials, font=font)
    tw = bbox[2] - bbox[0]
    th = bbox[3] - bbox[1]
    draw.text(((size - tw) / 2 - bbox[0], (size - th) / 2 - bbox[1] - 12), initials, font=font, fill=(255, 255, 255, 255))
    img.save(dest, format="PNG")


# =============================================================================
# Copilot Studio Solution .zip — clone canonical, swap names + instructions
# =============================================================================

def build_agent_instructions(stack: dict) -> str:
    integrations = ", ".join(stack["integrations"])
    feats = "\n".join(f"- {f}" for f in stack["features"])
    return f"""# {stack["name"]} Agent — Instructions

## Identity
You are the {stack['name']} Agent, an industry-shaped specialist for {industry_label(stack)}.

## Mission
{stack['description']}

## Capabilities
{feats}

## Tools
You can call connectors and actions for the following integrations:
{integrations}

## Behavior rules
1. NEVER fabricate data. If required input is missing, ASK for it explicitly.
2. Stay in scope: only handle requests inside the {industry_label(stack)} domain. For out-of-scope requests, politely decline and redirect.
3. Cite sources when you call tools / connectors. Surface the system you read from.
4. Persist state to Dataverse / D365 where appropriate.
5. Prefer structured output (tables, bullet lists) over freeform prose for actionable answers.
"""


def write_solution_zip(stack: dict, dest: Path) -> None:
    """Clone the canonical KnowMyCustomer solution zip and rewrite identifiers
    + instructions for this stack. Result is structurally a real Dataverse
    solution; final import-time validation is up to Copilot Studio."""
    if not TEMPLATE_ZIP.exists():
        raise FileNotFoundError(f"Template solution zip not found at {TEMPLATE_ZIP}")

    slug = slug_camel(stack)
    bot_id = re.sub(r"[^a-z0-9]", "", stack["id"]) or "stack"
    new_prefix = f"cat_{bot_id}"  # match existing publisher prefix `cat`
    old_prefix = "cat_knowmycustomer"
    instructions = build_agent_instructions(stack)

    # Read template into memory and rewrite paths/contents on the fly
    with zipfile.ZipFile(TEMPLATE_ZIP, "r") as zin:
        files = []
        for name in zin.namelist():
            data = zin.read(name)
            new_name = name.replace(old_prefix, new_prefix)
            files.append((new_name, data))

    # Substitutions inside text-ish files
    text_exts = (".xml", ".json", ".yml", ".yaml", "/data", "/configuration.json")

    def is_text(name: str) -> bool:
        return name.endswith(text_exts) or "botcomponent.xml" in name or "/data" in name or "/bot.xml" in name or name.endswith("solution.xml") or name.endswith("customizations.xml") or name.endswith("[Content_Types].xml")

    rewritten = []
    for name, data in files:
        if is_text(name):
            try:
                txt = data.decode("utf-8")
            except UnicodeDecodeError:
                rewritten.append((name, data))
                continue
            txt = txt.replace(old_prefix, new_prefix)
            txt = txt.replace("KnowMyCustomer", slug)
            txt = txt.replace("Know My Customer", stack["name"])
            txt = txt.replace("PowerCat", "PowerCat")  # publisher kept; rename if you want a custom publisher
            # Solution metadata
            if name == "solution.xml":
                txt = re.sub(r"<UniqueName>[^<]+</UniqueName>", f"<UniqueName>{slug}</UniqueName>", txt, count=1)
                txt = re.sub(
                    r'<LocalizedName description="[^"]+" languagecode="1033" />',
                    f'<LocalizedName description="{stack["name"]}" languagecode="1033" />',
                    txt, count=1,
                )
                txt = re.sub(r"<Version>[^<]+</Version>", "<Version>1.0.0.0</Version>", txt, count=1)
            # Swap the gpt.default data file's instructions
            if name.endswith(f"{new_prefix}.gpt.default/data"):
                txt = _replace_yaml_instructions(txt, instructions)
            rewritten.append((name, txt.encode("utf-8")))
        else:
            rewritten.append((name, data))

    # Write the zip
    dest.parent.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(dest, "w", zipfile.ZIP_DEFLATED) as zout:
        for name, data in rewritten:
            zout.writestr(name, data)


def _replace_yaml_instructions(yaml_text: str, new_instructions: str) -> str:
    """Best-effort replacement of the `instructions: |` block scalar with the
    stack-specific instructions. Falls back to inserting if not found."""
    indent = "  "
    new_block = "instructions: |\n" + "\n".join(indent + ln for ln in new_instructions.splitlines()) + "\n"

    # Find existing instructions block
    m = re.search(r"^instructions:\s*\|\s*\n", yaml_text, flags=re.MULTILINE)
    if not m:
        # No instructions block — prepend
        return new_block + yaml_text

    start = m.start()
    block_start = m.end()
    # Walk lines until indentation drops below indent (or EOF)
    lines = yaml_text[block_start:].splitlines(keepends=True)
    body_end = block_start
    for ln in lines:
        if ln.strip() == "":
            body_end += len(ln)
            continue
        # If line starts with the indent, it belongs to the block
        if ln.startswith(indent) or ln.startswith("  "):
            body_end += len(ln)
            continue
        break

    return yaml_text[:start] + new_block + yaml_text[body_end:]


# =============================================================================
# metadata.json
# =============================================================================

def write_metadata(stack: dict, dest: Path) -> None:
    pretty = stack["name"]
    slug = slug_camel(stack)
    metadata = {
        "id": f"{stack['id']}_stack",
        "name": f"{pretty} Agent Stack",
        "version": "1.0.0.0",
        "description": stack["description"],
        "category": stack["industry"],
        "industry_label": industry_label(stack),
        "complexity": "intermediate",
        "features": stack["features"],
        "benefits": stack["benefits"],
        "starters": stack["starters"],
        "technicalRequirements": {
            "platforms": ["Windows", "macOS", "Linux"],
            "dependencies": ["Python 3.11+", "requests", "json"],
            "integrations": stack["integrations"],
        },
        "components": [
            {
                "name": stack["agent_file"],
                "description": stack["description"],
                "role": "Primary processing engine (Azure Function / rapp_ai-style)",
            }
        ],
        "deliverables": {
            "readme": "README.md",
            "solution_zip": f"{slug}_v1.0.0.0.zip",
            "setup_guide_pdf": f"{pretty} Agent - Setup Guide.pdf",
            "overview_deck_pptx": f"{pretty} Agent - Overview Deck.pptx",
            "eval_test_plan_pdf": f"{pretty} Agent - Evaluation Test Plan.pdf",
            "eval_test_set_csv": f"{pretty} Agent - Evaluation Test Set.csv",
            "icon_png": f"{pretty} Icon.png",
            "agent_py": f"agents/{stack['agent_file']}",
            "architecture_copilot_studio": "architecture/copilot_studio.mmd",
            "architecture_azure_function": "architecture/azure_function.mmd",
        },
    }
    dest.write_text(json.dumps(metadata, indent=2) + "\n")


# =============================================================================
# Top-level driver
# =============================================================================

def write_stack(stack: dict) -> None:
    """Render a stack bundle.

    Additive — only the canonical bundle files are overwritten. Anything the
    user has added alongside (e.g. CUSTOM_ACTION_SETUP.md, an azure_function/
    Function App package) is preserved. Existing rich agent implementations
    are also preserved (the scaffold is only written when no file exists).
    """
    folder = ROOT / pretty_folder(stack)
    folder.mkdir(parents=True, exist_ok=True)

    pretty = stack["name"]
    slug = slug_camel(stack)

    write_readme(stack, folder / "README.md")
    write_setup_guide_pdf(stack, folder / f"{pretty} Agent - Setup Guide.pdf")
    write_eval_plan_pdf(stack, folder / f"{pretty} Agent - Evaluation Test Plan.pdf")
    write_eval_csv(stack, folder / f"{pretty} Agent - Evaluation Test Set.csv")
    write_icon_png(stack, folder / f"{pretty} Icon.png")
    write_overview_deck(stack, folder / f"{pretty} Agent - Overview Deck.pptx")
    write_solution_zip(stack, folder / f"{slug}_v1.0.0.0.zip")

    agents_dir = folder / "agents"
    agents_dir.mkdir(exist_ok=True)
    agent_path = agents_dir / stack["agent_file"]
    # Only write the scaffold when there's no agent yet — protect rich
    # hand-built implementations that downstream users have committed.
    if not agent_path.exists():
        write_agent_py(stack, agent_path)

    write_architecture(stack, folder / "architecture")
    write_metadata(stack, folder / "metadata.json")


def write_top_readme() -> None:
    by_industry: dict[str, list[dict]] = {}
    for s in STACKS:
        by_industry.setdefault(s["industry"], []).append(s)
    lines = [
        "# Proposed Industry Agent Stacks",
        "",
        "Portable, anonymous, industry-shaped agent stacks ready to merge into",
        "[github.com/microsoft/m365-agent-templates](https://github.com/microsoft/m365-agent-templates)",
        "or [github.com/kody-w/AI-Agent-Templates](https://github.com/kody-w/AI-Agent-Templates).",
        "None are currently in either repo or in the RAR `@aibast-agents-library` registry.",
        "",
        f"Total stacks: **{len(STACKS)}** across **{len(by_industry)}** industries.",
        "",
        "Each stack ships the full M365 deliverable bundle:",
        "",
        "- README.md",
        "- `<Pretty Name> Agent - Setup Guide.pdf` (canonical 7-section guide)",
        "- `<Pretty Name> Agent - Overview Deck.pptx` (11-slide overview)",
        "- `<Pretty Name> Agent - Evaluation Test Plan.pdf`",
        "- `<Pretty Name> Agent - Evaluation Test Set.csv`",
        "- `<Pretty Name> Icon.png`",
        "- `<Slug>_v1.0.0.0.zip` — Copilot Studio solution package (clone of the canonical export, with this stack's instructions baked in)",
        "- `agents/<agent>.py` — code-first BasicAgent variant for the rapp_ai-style Azure Function runtime",
        "- `architecture/copilot_studio.{mmd,html}` and `architecture/azure_function.{mmd,html}`",
        "- `metadata.json`",
        "",
        "## Generating",
        "",
        "```bash",
        "python3 _generate.py",
        "```",
        "",
        "Requires: `python-pptx`, `reportlab`, `Pillow`. The canonical solution zip we clone is at `_tools/_template_solution.zip`.",
        "",
        "## Forge / Deploy (optional)",
        "",
        "`_tools/copilot_studio_forge_agent.py` and `_tools/copilot_studio_deploy_agent.py` are vendored for re-forging stacks from RAPP swarms or pushing a packaged solution into a real Dataverse environment. Both require the brainstem environment to run.",
        "",
        "## Stacks",
        "",
    ]
    industry_order = sorted(by_industry.keys())
    for industry in industry_order:
        lines.append(f"### {industry.replace('_', ' ').title()} ({len(by_industry[industry])})")
        lines.append("")
        for s in by_industry[industry]:
            lines.append(f"- **[{s['name']}]({s['name'].replace(' ', '%20')}/README.md)** — {s['description']}")
        lines.append("")
    (ROOT / "README.md").write_text("\n".join(lines))


